+
+        var index = randomIdentifier();
+        prepareCreate(index).setSettings(indexSettings(1, 1)).get();
+        ensureGreen(index);
+
+        var repositoryName = "repository";
+        var snapshotName = randomIdentifier();
+        assertAcked(
+            clusterAdmin().preparePutRepository(repositoryName)
+                .setType("fs")
