+            existingComponentTemplates,
+            existingComposableTemplates,
+            ingestPipelines,
+            existingPolicies,
+            nodes
+        );
+        ClusterChangedEvent realEvent = new ClusterChangedEvent(
+            "created-from-test",
+            cs,
+            ClusterState.builder(new ClusterName("test")).build()
